INSERT INTO ui_messages (key, language_code, text) VALUES
 ('exports.dataset.mandi_pulse_member_crops', 'en', 'mandi pulse — member crops (unsigned)'),
 ('exports.dataset.mandi_pulse_member_crops', 'hi', 'मंडी पल्स — सदस्य फ़सलें (बिना हस्ताक्षर)'),
 ('exports.dataset.mandi_pulse_member_crops', 'gu', 'મંડી પલ્સ — સભ્ય પાક (સહી વગર)'),
 ('exports.dataset.demand_map', 'en', 'demand map (unsigned)'),
 ('exports.dataset.demand_map', 'hi', 'माँग नक्शा (बिना हस्ताक्षर)'),
 ('exports.dataset.demand_map', 'gu', 'માંગ નકશો (સહી વગર)'),
 ('exports.dataset.wastage_events', 'en', 'wastage events (unsigned)'),
 ('exports.dataset.wastage_events', 'hi', 'नुकसान घटनाएँ (बिना हस्ताक्षर)'),
 ('exports.dataset.wastage_events', 'gu', 'નુકસાન ઘટનાઓ (સહી વગર)'),
 ('exports.dataset.report_run', 'en', 'report (watermarked, unsigned)'),
 ('exports.dataset.report_run', 'hi', 'रिपोर्ट (वॉटरमार्क सहित, बिना हस्ताक्षर)'),
 ('exports.dataset.report_run', 'gu', 'રિપોર્ટ (વૉટરમાર્ક સાથે, સહી વગર)'),
 ('insights.method.member_crops', 'en', 'Member crops tracked = the distinct crops in a published listing of this cooperative today, or declared in a crop season (planned, sown or harvested) of this year or last. Source: listings, crop seasons.'),
 ('insights.method.member_crops', 'hi', 'ट्रैक की गई सदस्य फ़सलें = आज इस समिति की किसी प्रकाशित लिस्टिंग में मौजूद, या इस साल या पिछले साल के किसी फ़सल मौसम (नियोजित, बोई गई या कटी) में घोषित अलग-अलग फ़सलें। स्रोत: लिस्टिंग, फ़सल मौसम।'),
 ('insights.method.member_crops', 'gu', 'ટ્રૅક થતા સભ્ય પાક = આજે આ મંડળીની કોઈ પ્રકાશિત લિસ્ટિંગમાં હાજર, અથવા આ વર્ષ કે ગયા વર્ષની કોઈ પાક ઋતુ (આયોજિત, વાવેલી કે લણેલી) માં જાહેર કરેલા અલગ અલગ પાક. સ્રોત: લિસ્ટિંગ, પાક ઋતુ.'),
 ('insights.method.mandi_modal', 'en', 'Modal = the latest accepted modal price observed at that mandi for the crop in the last 14 days, as published; change = against the same mandi''s previous earlier day, in basis points, truncated toward zero. Source: mandi prices.'),
 ('insights.method.mandi_modal', 'hi', 'मॉडल = पिछले 14 दिनों में उस मंडी में उस फ़सल का सबसे नया स्वीकृत मॉडल भाव, जैसा प्रकाशित हुआ; बदलाव = उसी मंडी के पिछले दिन के भाव से, बेसिस पॉइंट में, शून्य की ओर काटकर। स्रोत: मंडी भाव।'),
 ('insights.method.mandi_modal', 'gu', 'મોડલ = છેલ્લા 14 દિવસમાં તે મંડીમાં તે પાકનો સૌથી નવો સ્વીકૃત મોડલ ભાવ, જેમ પ્રકાશિત થયો; ફેરફાર = તે જ મંડીના આગલા દિવસના ભાવ સામે, બેસિસ પોઇન્ટમાં, શૂન્ય તરફ કાપીને. સ્રોત: મંડી ભાવ.'),
 ('insights.method.listed_stock', 'en', 'Listed stock = the quantity still available on this cooperative''s published listings, per crop and unit. It is what is up for sale, not what is held in store. Source: listings.'),
 ('insights.method.listed_stock', 'hi', 'लिस्टेड स्टॉक = इस समिति की प्रकाशित लिस्टिंग पर अभी उपलब्ध मात्रा, हर फ़सल और इकाई के अनुसार। यह बिक्री के लिए रखा माल है, गोदाम में रखा माल नहीं। स्रोत: लिस्टिंग।'),
 ('insights.method.listed_stock', 'gu', 'લિસ્ટેડ સ્ટૉક = આ મંડળીની પ્રકાશિત લિસ્ટિંગ પર હજી ઉપલબ્ધ જથ્થો, દરેક પાક અને એકમ મુજબ. આ વેચાણ માટે મૂકેલો માલ છે, ગોદામમાં રાખેલો માલ નહીં. સ્રોત: લિસ્ટિંગ.'),
 ('insights.method.alerts_active', 'en', 'Price alerts active = alerts members set for themselves that are switched on today. Source: price alerts.'),
 ('insights.method.alerts_active', 'hi', 'सक्रिय भाव अलर्ट = सदस्यों द्वारा अपने लिए लगाए गए वे अलर्ट जो आज चालू हैं। स्रोत: भाव अलर्ट।'),
 ('insights.method.alerts_active', 'gu', 'સક્રિય ભાવ અલર્ટ = સભ્યોએ પોતાના માટે મૂકેલા અલર્ટ જે આજે ચાલુ છે. સ્રોત: ભાવ અલર્ટ.'),
 ('insights.method.alerts_fired', 'en', 'Fired this week = alert triggers recorded since Monday 00:00 IST. Source: price alert triggers.'),
 ('insights.method.alerts_fired', 'hi', 'इस सप्ताह बजे = सोमवार 00:00 IST से दर्ज अलर्ट ट्रिगर। स्रोत: भाव अलर्ट ट्रिगर।'),
 ('insights.method.alerts_fired', 'gu', 'આ અઠવાડિયે વાગ્યા = સોમવાર 00:00 IST થી નોંધાયેલા અલર્ટ ટ્રિગર. સ્રોત: ભાવ અલર્ટ ટ્રિગર.'),
 ('insights.method.qty_wanted', 'en', 'Quantity wanted = the requirement''s quantity less what has already been accepted against it, in its own unit. Source: requirements.'),
 ('insights.method.qty_wanted', 'hi', 'चाही गई मात्रा = माँग की मात्रा में से वह घटाकर जो पहले ही स्वीकार हो चुकी है, माँग की अपनी इकाई में। स्रोत: माँगें।'),
 ('insights.method.qty_wanted', 'gu', 'જોઈતો જથ્થો = માંગનો જથ્થો, તેમાંથી પહેલેથી સ્વીકારાયેલું બાદ કરીને, માંગના પોતાના એકમમાં. સ્રોત: માંગ.'),
 ('insights.method.stock_fit', 'en', 'Member stock fit = the quantity available on this cooperative''s published listings of the same crop in the same unit (the buyer''s own excluded), against the quantity wanted: covers, partial or none. Aggregates only; a member''s own figures appear only after that member consented to a quote on this requirement. Source: listings, requirement consents.'),
 ('insights.method.stock_fit', 'hi', 'सदस्य स्टॉक मेल = इस समिति की उसी फ़सल और उसी इकाई की प्रकाशित लिस्टिंग पर उपलब्ध मात्रा (खरीदार की अपनी को छोड़कर), चाही गई मात्रा के सामने: पूरा, आंशिक या नहीं। केवल कुल योग; किसी सदस्य के अपने आँकड़े तभी दिखते हैं जब उस सदस्य ने इस माँग पर कोटेशन की सहमति दी हो। स्रोत: लिस्टिंग, माँग सहमतियाँ।'),
 ('insights.method.stock_fit', 'gu', 'સભ્ય સ્ટૉક મેળ = આ મંડળીની તે જ પાક અને તે જ એકમની પ્રકાશિત લિસ્ટિંગ પર ઉપલબ્ધ જથ્થો (ખરીદારની પોતાની સિવાય), જોઈતા જથ્થા સામે: પૂરો, આંશિક કે નહીં. ફક્ત કુલ સરવાળો; કોઈ સભ્યના પોતાના આંકડા ત્યારે જ દેખાય જ્યારે તે સભ્યએ આ માંગ પર ભાવની સંમતિ આપી હોય. સ્રોત: લિસ્ટિંગ, માંગ સંમતિઓ.'),
 ('insights.method.demand_value', 'en', 'Value = quantity wanted × the buyer''s per-unit budget ceiling (and floor, when posted), in the requirement''s currency, rounded down. Source: requirements.'),
 ('insights.method.demand_value', 'hi', 'मूल्य = चाही गई मात्रा × खरीदार का प्रति इकाई बजट ऊपरी सीमा (और न्यूनतम, जब दिया हो), माँग की मुद्रा में, नीचे की ओर पूर्णांकित। स्रोत: माँगें।'),
 ('insights.method.demand_value', 'gu', 'મૂલ્ય = જોઈતો જથ્થો × ખરીદારનું એકમ દીઠ બજેટ મહત્તમ (અને ન્યૂનતમ, જ્યારે આપ્યું હોય), માંગના ચલણમાં, નીચે તરફ પૂર્ણાંકિત. સ્રોત: માંગ.'),
 ('insights.method.geo_reach', 'en', 'Within reach = the delivery pincode maps (pincode → district) to a district where this cooperative is registered or holds a located published listing. A requirement without a mapped pincode is counted as unknown, never as near. Source: pincodes, regions, listings.'),
 ('insights.method.geo_reach', 'hi', 'पहुँच में = डिलीवरी पिनकोड (पिनकोड → ज़िला) उस ज़िले में आता है जहाँ यह समिति पंजीकृत है या जहाँ इसकी स्थान वाली प्रकाशित लिस्टिंग है। बिना मिलान पिनकोड वाली माँग अज्ञात गिनी जाती है, कभी पास नहीं। स्रोत: पिनकोड, क्षेत्र, लिस्टिंग।'),
 ('insights.method.geo_reach', 'gu', 'પહોંચમાં = ડિલિવરી પિનકોડ (પિનકોડ → જિલ્લો) એવા જિલ્લામાં આવે જ્યાં આ મંડળી નોંધાયેલી છે અથવા તેની સ્થાન ધરાવતી પ્રકાશિત લિસ્ટિંગ છે. મેળ વગરના પિનકોડવાળી માંગ અજ્ઞાત ગણાય છે, ક્યારેય નજીક નહીં. સ્રોત: પિનકોડ, પ્રદેશ, લિસ્ટિંગ.'),
 ('insights.method.measured_loss', 'en', 'Measured loss = the money value each source recorded for a loss in the window, per currency: the refund on a returned order, the priced amount of a rejected milk pour, the refund of a dispute opened from a POD rejection, a recorded cold-chain loss, a POD reviewer''s entered variance. A POD rejection and the dispute it opened count once (the dispute''s refund when it exists). Losses with no recorded money value are counted by quantity, per unit, beside it. Source: wastage events.'),
 ('insights.method.measured_loss', 'hi', 'मापा गया नुकसान = अवधि में हर स्रोत द्वारा किसी नुकसान का दर्ज धन मूल्य, हर मुद्रा के अनुसार: लौटाए गए ऑर्डर पर रिफ़ंड, अस्वीकृत दूध डालने की आँकी गई राशि, POD अस्वीकृति से खुले विवाद का रिफ़ंड, दर्ज कोल्ड-चेन नुकसान, POD समीक्षक द्वारा दर्ज अंतर। एक POD अस्वीकृति और उससे खुला विवाद एक ही बार गिने जाते हैं (विवाद का रिफ़ंड, जब हो)। जिन नुकसानों का कोई धन मूल्य दर्ज नहीं, वे मात्रा से, हर इकाई के अनुसार, साथ में गिने जाते हैं। स्रोत: नुकसान घटनाएँ।'),
 ('insights.method.measured_loss', 'gu', 'માપેલું નુકસાન = સમયગાળામાં દરેક સ્રોતે કોઈ નુકસાન માટે નોંધેલું નાણાકીય મૂલ્ય, દરેક ચલણ મુજબ: પરત ઓર્ડર પર રિફંડ, નામંજૂર દૂધ રેડાણની આંકેલી રકમ, POD નામંજૂરીથી ખુલેલા વિવાદનું રિફંડ, નોંધાયેલું કોલ્ડ-ચેઇન નુકસાન, POD સમીક્ષકે નોંધેલો તફાવત. એક POD નામંજૂરી અને તેનાથી ખુલેલો વિવાદ એક જ વાર ગણાય છે (વિવાદનું રિફંડ, જ્યારે હોય). જે નુકસાનનું કોઈ નાણાકીય મૂલ્ય નોંધાયું નથી તે જથ્થાથી, દરેક એકમ મુજબ, સાથે ગણાય છે. સ્રોત: નુકસાન ઘટનાઓ.'),
 ('insights.method.loss_share', 'en', 'Share of GMV = measured loss ÷ the goods value of orders completed in the same window (the AGM method), in basis points, rounded down; shown only when both are in one currency.'),
 ('insights.method.loss_share', 'hi', 'GMV में हिस्सा = मापा गया नुकसान ÷ उसी अवधि में पूरे हुए ऑर्डरों का माल मूल्य (AGM पद्धति), बेसिस पॉइंट में, नीचे की ओर पूर्णांकित; तभी दिखाया जाता है जब दोनों एक ही मुद्रा में हों।'),
 ('insights.method.loss_share', 'gu', 'GMV માં હિસ્સો = માપેલું નુકસાન ÷ તે જ સમયગાળામાં પૂર્ણ થયેલા ઓર્ડરનું માલ મૂલ્ય (AGM પદ્ધતિ), બેસિસ પોઇન્ટમાં, નીચે તરફ પૂર્ણાંકિત; બંને એક જ ચલણમાં હોય ત્યારે જ દર્શાવાય છે.'),
 ('insights.method.loss_split', 'en', 'Split = the same measured loss by where its source places it: transit (POD rejections, POD disputes, shipment cold chain), storage (other cold chain), milk (rejected pours, cooler cold chain), other (returns).'),
 ('insights.method.loss_split', 'hi', 'बँटवारा = वही मापा गया नुकसान, इसके स्रोत के अनुसार: परिवहन (POD अस्वीकृतियाँ, POD विवाद, शिपमेंट कोल्ड चेन), भंडारण (अन्य कोल्ड चेन), दूध (अस्वीकृत दूध, कूलर कोल्ड चेन), अन्य (वापसी)।'),
 ('insights.method.loss_split', 'gu', 'વિભાજન = તે જ માપેલું નુકસાન, તેના સ્રોત મુજબ: પરિવહન (POD નામંજૂરી, POD વિવાદ, શિપમેન્ટ કોલ્ડ ચેઇન), સંગ્રહ (અન્ય કોલ્ડ ચેઇન), દૂધ (નામંજૂર દૂધ, કૂલર કોલ્ડ ચેઇન), અન્ય (પરત).'),
 ('insights.method.funnel', 'en', 'Funnel = per lesson, the learners with a progress record on it (started) and those who completed it. Source: lesson progress.'),
 ('insights.method.funnel', 'hi', 'फ़नल = हर पाठ पर, जिन शिक्षार्थियों का प्रगति रिकॉर्ड है (शुरू किया) और जिन्होंने उसे पूरा किया। स्रोत: पाठ प्रगति।'),
 ('insights.method.funnel', 'gu', 'ફનલ = દરેક પાઠ પર, જે શીખનારનો પ્રગતિ રેકોર્ડ છે (શરૂ કર્યું) અને જેમણે તે પૂર્ણ કર્યો. સ્રોત: પાઠ પ્રગતિ.'),
 ('insights.method.quiz_miss', 'en', 'Missed = per question, the share of captured answers that were not correct (an unanswered question counts as missed), over every attempt, in basis points rounded down. Shown only when at least 50 distinct learners have captured answers on the lesson. Source: quiz answers.'),
 ('insights.method.quiz_miss', 'hi', 'चूके = हर प्रश्न पर, दर्ज उत्तरों में से जो सही नहीं थे उनका हिस्सा (बिना उत्तर वाला प्रश्न चूका गिना जाता है), हर प्रयास पर, बेसिस पॉइंट में नीचे की ओर पूर्णांकित। तभी दिखाया जाता है जब पाठ पर कम से कम 50 अलग शिक्षार्थियों के उत्तर दर्ज हों। स्रोत: क्विज़ उत्तर।'),
 ('insights.method.quiz_miss', 'gu', 'ચૂક્યા = દરેક પ્રશ્ન પર, નોંધાયેલા જવાબોમાંથી જે સાચા ન હતા તેનો હિસ્સો (જવાબ વગરનો પ્રશ્ન ચૂક્યો ગણાય છે), દરેક પ્રયાસ પર, બેસિસ પોઇન્ટમાં નીચે તરફ પૂર્ણાંકિત. પાઠ પર ઓછામાં ઓછા 50 અલગ શીખનારના જવાબ નોંધાયા હોય ત્યારે જ દર્શાવાય છે. સ્રોત: ક્વિઝ જવાબો.'),
 ('insights.method.watch_curve', 'en', 'Watch seconds by IST hour = the seconds learners played, placed in the IST hour they started: the app''s own interval when it sends one, otherwise the growth in seconds watched placed at the time the server received the report. Shown only at 50 distinct learners. Source: watch events.'),
 ('insights.method.watch_curve', 'hi', 'IST घंटे के अनुसार देखे गए सेकंड = शिक्षार्थियों द्वारा चलाए गए सेकंड, उस IST घंटे में जिसमें वे शुरू हुए: ऐप का अपना अंतराल जब वह भेजे, अन्यथा देखे गए सेकंड में बढ़ोतरी, उस समय रखी गई जब सर्वर को रिपोर्ट मिली। केवल 50 अलग शिक्षार्थियों पर दिखाया जाता है। स्रोत: देखने की घटनाएँ।'),
 ('insights.method.watch_curve', 'gu', 'IST કલાક મુજબ જોયેલી સેકન્ડ = શીખનારોએ ચલાવેલી સેકન્ડ, તે IST કલાકમાં જેમાં તે શરૂ થઈ: ઍપ પોતાનો અંતરાલ મોકલે ત્યારે તે, નહીં તો જોયેલી સેકન્ડમાં વધારો, સર્વરને રિપોર્ટ મળ્યો તે સમયે મૂકેલો. ફક્ત 50 અલગ શીખનારે દર્શાવાય છે. સ્રોત: જોવાની ઘટનાઓ.'),
 ('insights.refusal.NO_STOCK_DECLARATION', 'en', 'Stored stock is not shown: members declare crop seasons with a yield, never what they hold in store, so there is no stock declaration to add up. Listed stock (what is up for sale) is shown instead.'),
 ('insights.refusal.NO_STOCK_DECLARATION', 'hi', 'भंडारित स्टॉक नहीं दिखाया गया: सदस्य फ़सल मौसम में उपज घोषित करते हैं, गोदाम में रखा माल कभी नहीं, इसलिए जोड़ने के लिए कोई स्टॉक घोषणा नहीं है। इसकी जगह लिस्टेड स्टॉक (जो बिक्री पर है) दिखाया गया है।'),
 ('insights.refusal.NO_STOCK_DECLARATION', 'gu', 'સંગ્રહિત સ્ટૉક દર્શાવ્યો નથી: સભ્યો પાક ઋતુમાં ઉપજ જાહેર કરે છે, ગોદામમાં રાખેલો માલ ક્યારેય નહીં, તેથી સરવાળો કરવા કોઈ સ્ટૉક જાહેરાત નથી. તેના બદલે લિસ્ટેડ સ્ટૉક (જે વેચાણ પર છે) દર્શાવ્યો છે.'),
 ('insights.refusal.NO_CAUSAL_METHOD', 'en', 'Members who sold because of an alert is not shown: an alert followed by a sale is not proof the alert caused it, and no method for that claim is published.'),
 ('insights.refusal.NO_CAUSAL_METHOD', 'hi', 'अलर्ट के कारण बेचने वाले सदस्य नहीं दिखाए गए: अलर्ट के बाद हुई बिक्री इस बात का प्रमाण नहीं कि अलर्ट ने बिक्री कराई, और इस दावे की कोई पद्धति प्रकाशित नहीं है।'),
 ('insights.refusal.NO_CAUSAL_METHOD', 'gu', 'અલર્ટને કારણે વેચનાર સભ્યો દર્શાવ્યા નથી: અલર્ટ પછીનું વેચાણ એ સાબિતી નથી કે અલર્ટે વેચાણ કરાવ્યું, અને આ દાવાની કોઈ પદ્ધતિ પ્રકાશિત નથી.'),
 ('insights.refusal.NO_REGISTERED_MODEL', 'en', 'The price band is not shown: no price model is registered on this platform, so there is no band and no confidence to print.'),
 ('insights.refusal.NO_REGISTERED_MODEL', 'hi', 'भाव बैंड नहीं दिखाया गया: इस प्लेटफ़ॉर्म पर कोई भाव मॉडल पंजीकृत नहीं है, इसलिए छापने के लिए न कोई बैंड है न कोई भरोसा।'),
 ('insights.refusal.NO_REGISTERED_MODEL', 'gu', 'ભાવ બૅન્ડ દર્શાવ્યો નથી: આ પ્લેટફોર્મ પર કોઈ ભાવ મૉડલ નોંધાયેલું નથી, તેથી છાપવા માટે ન કોઈ બૅન્ડ છે ન કોઈ વિશ્વાસ.'),
 ('insights.refusal.NO_PRICE_ON_REQUIREMENT', 'en', 'Value is not shown: this requirement carries no per-unit budget, so quantity times a price cannot be computed.'),
 ('insights.refusal.NO_PRICE_ON_REQUIREMENT', 'hi', 'मूल्य नहीं दिखाया गया: इस माँग में प्रति इकाई बजट नहीं है, इसलिए मात्रा गुणा भाव नहीं निकाला जा सकता।'),
 ('insights.refusal.NO_PRICE_ON_REQUIREMENT', 'gu', 'મૂલ્ય દર્શાવ્યું નથી: આ માંગમાં એકમ દીઠ બજેટ નથી, તેથી જથ્થો ગુણ્યા ભાવ ગણી શકાતો નથી.'),
 ('insights.refusal.NO_GEO_REACH', 'en', 'Within reach is not shown: this cooperative has no district on record (no region on the organisation and no located listing), so reach cannot be judged.'),
 ('insights.refusal.NO_GEO_REACH', 'hi', 'पहुँच नहीं दिखाई गई: इस समिति का कोई ज़िला दर्ज नहीं है (संगठन पर कोई क्षेत्र नहीं और कोई स्थान वाली लिस्टिंग नहीं), इसलिए पहुँच तय नहीं की जा सकती।'),
 ('insights.refusal.NO_GEO_REACH', 'gu', 'પહોંચ દર્શાવી નથી: આ મંડળીનો કોઈ જિલ્લો નોંધાયેલો નથી (સંસ્થા પર કોઈ પ્રદેશ નથી અને કોઈ સ્થાન ધરાવતી લિસ્ટિંગ નથી), તેથી પહોંચ નક્કી થઈ શકતી નથી.'),
 ('insights.refusal.NO_UNMET_DEMAND_METHOD', 'en', 'What buyers near you cannot find is not shown: there is no published method for unmet demand.'),
 ('insights.refusal.NO_UNMET_DEMAND_METHOD', 'hi', 'आसपास के खरीदार जो नहीं पा रहे, वह नहीं दिखाया गया: अधूरी माँग की कोई प्रकाशित पद्धति नहीं है।'),
 ('insights.refusal.NO_UNMET_DEMAND_METHOD', 'gu', 'નજીકના ખરીદારો જે મેળવી શકતા નથી તે દર્શાવ્યું નથી: અધૂરી માંગની કોઈ પ્રકાશિત પદ્ધતિ નથી.'),
 ('insights.refusal.EXTERNAL_STATISTIC_UNSOURCED', 'en', 'The national loss figure is not shown: it is an outside statistic with no source recorded on this platform.'),
 ('insights.refusal.EXTERNAL_STATISTIC_UNSOURCED', 'hi', 'राष्ट्रीय नुकसान का आँकड़ा नहीं दिखाया गया: यह बाहरी आँकड़ा है जिसका कोई स्रोत इस प्लेटफ़ॉर्म पर दर्ज नहीं है।'),
 ('insights.refusal.EXTERNAL_STATISTIC_UNSOURCED', 'gu', 'રાષ્ટ્રીય નુકસાનનો આંકડો દર્શાવ્યો નથી: તે બહારનો આંકડો છે જેનો કોઈ સ્રોત આ પ્લેટફોર્મ પર નોંધાયેલો નથી.'),
 ('insights.refusal.NO_COUNTERFACTUAL_METHOD', 'en', 'What saved money is not shown: a saving is a loss that did not happen, and no method measures that.'),
 ('insights.refusal.NO_COUNTERFACTUAL_METHOD', 'hi', 'किस चीज़ ने पैसा बचाया, यह नहीं दिखाया गया: बचत वह नुकसान है जो हुआ ही नहीं, और उसे मापने की कोई पद्धति नहीं है।'),
 ('insights.refusal.NO_COUNTERFACTUAL_METHOD', 'gu', 'શાનાથી પૈસા બચ્યા તે દર્શાવ્યું નથી: બચત એ નુકસાન છે જે થયું જ નહીં, અને તેને માપવાની કોઈ પદ્ધતિ નથી.'),
 ('insights.refusal.NO_WEIGHBRIDGE_OBJECT', 'en', 'Weighbridge slips are not shown: no weighbridge record exists on this platform.'),
 ('insights.refusal.NO_WEIGHBRIDGE_OBJECT', 'hi', 'तौल-काँटा पर्चियाँ नहीं दिखाई गईं: इस प्लेटफ़ॉर्म पर कोई तौल-काँटा रिकॉर्ड नहीं है।'),
 ('insights.refusal.NO_WEIGHBRIDGE_OBJECT', 'gu', 'વજનકાંટા સ્લિપ દર્શાવી નથી: આ પ્લેટફોર્મ પર કોઈ વજનકાંટા રેકોર્ડ નથી.'),
 ('insights.refusal.MANUAL_WASTAGE_REFUSED', 'en', 'A loss cannot be typed in: wastage is recorded only from its source (a refunded return, a rejected pour, a POD rejection or dispute, a recorded cold-chain loss).'),
 ('insights.refusal.MANUAL_WASTAGE_REFUSED', 'hi', 'नुकसान हाथ से नहीं लिखा जा सकता: नुकसान केवल अपने स्रोत से दर्ज होता है (रिफ़ंड हुई वापसी, अस्वीकृत दूध, POD अस्वीकृति या विवाद, दर्ज कोल्ड-चेन नुकसान)।'),
 ('insights.refusal.MANUAL_WASTAGE_REFUSED', 'gu', 'નુકસાન હાથે લખી શકાતું નથી: નુકસાન ફક્ત તેના સ્રોતથી નોંધાય છે (રિફંડ થયેલું પરત, નામંજૂર દૂધ, POD નામંજૂરી કે વિવાદ, નોંધાયેલું કોલ્ડ-ચેઇન નુકસાન).'),
 ('insights.refusal.NO_ANALYTICS_REPLICA', 'en', 'No analytics replica is provisioned: reports run on the primary database under a 60-second statement timeout, 92 days and 50,000 rows at most.'),
 ('insights.refusal.NO_ANALYTICS_REPLICA', 'hi', 'कोई एनालिटिक्स प्रतिकृति उपलब्ध नहीं: रिपोर्ट मुख्य डेटाबेस पर 60-सेकंड स्टेटमेंट सीमा में चलती हैं, अधिकतम 92 दिन और 50,000 पंक्तियाँ।'),
 ('insights.refusal.NO_ANALYTICS_REPLICA', 'gu', 'કોઈ ઍનાલિટિક્સ પ્રતિકૃતિ ઉપલબ્ધ નથી: રિપોર્ટ મુખ્ય ડેટાબેસ પર 60-સેકન્ડ સ્ટેટમેન્ટ મર્યાદામાં ચાલે છે, વધુમાં વધુ 92 દિવસ અને 50,000 પંક્તિઓ.'),
 ('insights.refusal.MEMBER_DIMENSION_NOT_OFFERED', 'en', 'Reports are aggregates: no member-level dimension is offered by the builder.'),
 ('insights.refusal.MEMBER_DIMENSION_NOT_OFFERED', 'hi', 'रिपोर्ट कुल योग हैं: बिल्डर सदस्य-स्तर का कोई आयाम नहीं देता।'),
 ('insights.refusal.MEMBER_DIMENSION_NOT_OFFERED', 'gu', 'રિપોર્ટ કુલ સરવાળા છે: બિલ્ડર સભ્ય-સ્તરનું કોઈ પરિમાણ આપતું નથી.'),
 ('insights.refusal.UNSIGNED_FOUNDER_PHYSICAL_KEY', 'en', 'The file is unsigned: signing needs a key held physically by the founder. Its sha256 is printed on the receipt.'),
 ('insights.refusal.UNSIGNED_FOUNDER_PHYSICAL_KEY', 'hi', 'फ़ाइल पर हस्ताक्षर नहीं है: हस्ताक्षर के लिए वह कुंजी चाहिए जो संस्थापक के पास भौतिक रूप से है। इसका sha256 रसीद पर छपा है।'),
 ('insights.refusal.UNSIGNED_FOUNDER_PHYSICAL_KEY', 'gu', 'ફાઇલ પર સહી નથી: સહી માટે એ ચાવી જોઈએ જે સ્થાપક પાસે ભૌતિક રીતે છે. તેનો sha256 રસીદ પર છપાયેલો છે.'),
 ('insights.refusal.BELOW_LEARNER_FLOOR', 'en', 'Not shown yet: this lesson needs at least 50 learners with captured data before per-lesson numbers show — small cohorts stay anonymous, by design.'),
 ('insights.refusal.BELOW_LEARNER_FLOOR', 'hi', 'अभी नहीं दिखाया गया: पाठ-स्तर के आँकड़े दिखने से पहले इस पाठ पर दर्ज डेटा वाले कम से कम 50 शिक्षार्थी चाहिए — छोटे समूह जानबूझकर गुमनाम रहते हैं।'),
 ('insights.refusal.BELOW_LEARNER_FLOOR', 'gu', 'હજી દર્શાવ્યું નથી: પાઠ-સ્તરના આંકડા દેખાય તે પહેલાં આ પાઠ પર નોંધાયેલા ડેટાવાળા ઓછામાં ઓછા 50 શીખનાર જોઈએ — નાના જૂથો જાણીજોઈને અનામી રહે છે.'),
 ('insights.refusal.NO_ADVISORY_GENERATOR', 'en', 'No fix suggestion is shown: no advisory generator exists on this platform; the drop-off is shown as it is.'),
 ('insights.refusal.NO_ADVISORY_GENERATOR', 'hi', 'कोई सुधार सुझाव नहीं दिखाया गया: इस प्लेटफ़ॉर्म पर कोई सलाह जनरेटर नहीं है; ड्रॉप-ऑफ़ जैसा है वैसा दिखाया गया है।'),
 ('insights.refusal.NO_ADVISORY_GENERATOR', 'gu', 'કોઈ સુધારા સૂચન દર્શાવ્યું નથી: આ પ્લેટફોર્મ પર કોઈ સલાહ જનરેટર નથી; ડ્રૉપ-ઑફ જેવું છે તેવું દર્શાવ્યું છે.'),
 ('insights.refusal.NO_CAPTURE_YET', 'en', 'No answers or watch time captured yet for this lesson. Capture began when this release was installed; nothing before that exists.'),
 ('insights.refusal.NO_CAPTURE_YET', 'hi', 'इस पाठ के लिए अभी कोई उत्तर या देखने का समय दर्ज नहीं हुआ। दर्ज करना इस रिलीज़ के लगने पर शुरू हुआ; उससे पहले का कुछ नहीं है।'),
 ('insights.refusal.NO_CAPTURE_YET', 'gu', 'આ પાઠ માટે હજી કોઈ જવાબ કે જોવાનો સમય નોંધાયો નથી. નોંધણી આ રિલીઝ લાગ્યા ત્યારે શરૂ થઈ; તે પહેલાંનું કંઈ નથી.')
